import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const LoginForm = () => {
  const [registrationId, setRegistrationId] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();

    // Dummy list of valid registration IDs (you’ll replace this later)
    const validIds = ['REG123', 'REG456', 'REG789'];

    if (validIds.includes(registrationId.trim().toUpperCase())) {
      setError('');
      navigate('/vote'); // redirect to voting page
    } else {
      setError('Invalid Registration ID. Please try again.');
    }
  };

  return (
    <div className="container mt-5">
      <h2 className="text-center mb-4">Student Login</h2>
      <form onSubmit={handleLogin} className="mx-auto" style={{ maxWidth: '400px' }}>
        <div className="mb-3">
          <label htmlFor="registrationId" className="form-label">Registration ID</label>
          <input
            type="text"
            className="form-control"
            id="registrationId"
            value={registrationId}
            onChange={(e) => setRegistrationId(e.target.value)}
            required
          />
        </div>
        {error && <div className="alert alert-danger">{error}</div>}
        <button type="submit" className="btn btn-primary w-100">Login</button>
      </form>
    </div>
  );
};

export default LoginForm;
